function canAsk(usage, today, limit) {
    const used = usage && usage.day === today ? usage.count : 0;
    if (limit === null)
        return { allowed: true, used, remaining: null };
    return { allowed: used < limit, used, remaining: Math.max(0, limit - used) };
}
