// ---- calculator
function historicalReturn(amountKobo, startPriceKobo, endPriceKobo, days) {
    if (!Number.isSafeInteger(amountKobo) || amountKobo <= 0)
        return { ok: false, error: "amount-required" };
    if (!Number.isFinite(days) || days <= 0)
        return { ok: false, error: "bad-period" };
    const shares = Math.floor(amountKobo / startPriceKobo);
    if (shares === 0)
        return { ok: false, error: "amount-too-small" };
    const invested = shares * startPriceKobo;
    const leftover = amountKobo - invested;
    const endValue = shares * endPriceKobo + leftover;
    const gain = endValue - amountKobo;
    const returnPct = Math.round((gain / amountKobo) * 1000) / 10;
    const cagrPct = days >= 365 ? Math.round((Math.pow(endValue / amountKobo, 365 / days) - 1) * 1000) / 10 : null;
    return { ok: true, result: { shares, investedKobo: invested, leftoverKobo: leftover, endValueKobo: endValue, gainKobo: gain, returnPct, cagrPct } };
}
/** Compound interest for the savings calculator: monthly compounding, kobo rounded at the end. */
function compound(principalKobo, monthlyKobo, annualRatePct, years) {
    const r = annualRatePct / 100 / 12;
    let bal = principalKobo;
    const months = Math.round(years * 12);
    for (let m = 0; m < months; m++)
        bal = bal * (1 + r) + monthlyKobo;
    const total = Math.round(bal);
    const contributed = principalKobo + monthlyKobo * months;
    return { totalKobo: total, contributedKobo: contributed, interestKobo: total - contributed };
}

// ---- search
// Universal search across companies, lessons and articles (build plan §4.10).
function normalise(s) {
    return s.toLowerCase().normalize("NFKD").replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();
}
/** Ranks title prefix > title word > keyword match. Empty query returns nothing. */
function search(items, query, limit = 20) {
    const q = normalise(query);
    if (!q)
        return [];
    const scored = items.flatMap((it) => {
        const t = normalise(it.title);
        const all = t + " " + normalise(it.subtitle + " " + it.keywords + " " + it.id);
        let score = 0;
        if (t.startsWith(q))
            score = 3;
        else if (t.split(" ").some((w) => w.startsWith(q)))
            score = 2;
        else if (q.split(" ").every((w) => all.includes(w)))
            score = 1;
        return score ? [{ it, score }] : [];
    });
    return scored.sort((a, b) => b.score - a.score || a.it.title.localeCompare(b.it.title)).slice(0, limit).map((s) => s.it);
}
/** Simple "did you mean": closest title word within edit distance 2. */
function suggest(items, query) {
    const q = normalise(query);
    if (q.length < 3)
        return null;
    let best = null;
    for (const it of items)
        for (const w of normalise(it.title).split(" ")) {
            if (w.length < 3)
                continue;
            const d = editDistance(q, w);
            if (d <= 2 && (!best || d < best.d))
                best = { w, d };
        }
    return best && best.w !== q ? best.w : null;
}
function editDistance(a, b) {
    const dp = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
    for (let j = 1; j <= b.length; j++)
        dp[0][j] = j;
    for (let i = 1; i <= a.length; i++)
        for (let j = 1; j <= b.length; j++)
            dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    return dp[a.length][b.length];
}

